import { atom, read, update } from 'claude-code'
import type { EngineInterface, Hook, MatchedHook, Timer } from 'claude-code'

import type { Answer, Aspect, OpenCard, Practice } from '../../../engine-protocol'
import { Answers } from '../../../logic/answer/answer'
import { DraftTranslations } from '../../../logic/draft-translation/draft-translation'
import { ElementKeys } from '../../../logic/element-key/element-key'
import { LingoSettings } from '../../../logic/lingo-settings/lingo-settings'
import { OpenCards } from '../../../logic/open-cards/open-cards'
import { PromptTranslations } from '../../../logic/prompt-translation/prompt-translation'
import { Pronunciations } from '../../../logic/pronunciation/pronunciation'
import { ReplyTranslations } from '../../../logic/reply-translation/reply-translation'
import { Result } from '../../../logic/result/result'
import { SpeakingPractice } from '../../../logic/speaking-practice/speaking-practice'
import { WordAspects } from '../../../logic/word-aspect/word-aspect'
import { WordCards } from '../../../logic/word-card/word-card'
import { WordLines } from '../../../logic/word-line/word-line'
import { draftBand } from '../../ui/draft-band/draft-band'
import { practiceBand } from '../../ui/practice-band/practice-band'
import { symbolLine } from '../../ui/read-aloud/read-aloud'
import type { Voice } from '../../ui/read-aloud/read-aloud'
import { REPLY_PANE, paragraphTranslation, replyBlock, replyPane } from '../../ui/reply-translation/reply-translation'
import { ticker } from '../../ui/ticker/ticker'
import { pendingTranslation, withTranslation } from '../../ui/translation-line/translation-line'
import { wordCard, wordLine } from '../../ui/word-card/word-card'

// 設定パネル（settings.tsx）が $.store に置いた設定。$ は import をまたいで渡せないので、ここでも読む
const settingsOf = async ($: EngineInterface) => LingoSettings.of(await $.store.get('settings'))

// 指示の鍵（PromptTranslations.key）→ その外国語版。送信のときに作り、行を描くときに引く。訳している間は null
const translations = atom({ plugin: 'claudelingo', key: 'translations' } as const, {})
// 指示のメッセージ（id）か返事の段落 → その下に開いている単語の絵
const cards = atom({ plugin: 'claudelingo', key: 'cards' } as const, {})
// 描いた絵（WordCards.saving の形）。ディスクには置かず、セッションの間だけ持つ
const drawn = atom({ plugin: 'claudelingo', key: 'drawn' } as const, {})

// 手順書「指示を外国語で示す」：訳す指示なら言い直しを頼み、行が引けるように残す
const showTranslation = async ($: EngineInterface, from: string, text: string) => {
  const request = PromptTranslations.request(await settingsOf($), { from, text }, (await $.command.list()).map(c => c.name))
  if (!request || !PromptTranslations.isNeeded(await $.session.surfaces())) return
  // 訳している間の印は、まだ訳の無い指示だけ（同じ文を送り直したなら、前の訳を出したまま待つ）
  await showTranslationOf($, text, all => (Object.hasOwn(all, PromptTranslations.key(text)) ? all[PromptTranslations.key(text)] : null))
  const translation = await Answers.of($.model.complete(request))
  await showTranslationOf($, text, () => translation)
}

// 訳が届いたらすぐ描き直させる（状態の変化だけでは、面によっては次の描画まで行が出ない）
const showTranslationOf = async ($: EngineInterface, text: string, change: (all: Record<string, Answer | null>) => Answer | null | undefined) => {
  await update($, translations, all => ({ ...all, [PromptTranslations.key(text)]: change(all) ?? null }))
  $.ui.invalidate('ui.render')
}

const rowOf = async ($: EngineInterface, row: string) => (await read($, cards))[row] ?? []

// 開いている絵は置き換えで変える（中を書き換えると Desktop が描き直さない）
const showCards = async ($: EngineInterface, row: string, change: (list: OpenCard[]) => OpenCard[]) => {
  await update($, cards, all => ({ ...all, [row]: change(all[row] ?? []) }))
  $.ui.invalidate('ui.render')
}

// 手順書「単語の絵を出す」：同じ絵が開いていれば閉じ、なければ下に並べる。描いた絵はセッションの間残し、二度目からはすぐ出す
const pressWord = async ($: EngineInterface, row: string, word: string, restated: string) => {
  const saved = WordCards.saved(await read($, drawn), { word, restated })
  const since = await $.clock.now()
  await showCards($, row, list => OpenCards.pressed(list, { word, since }, saved))
  if (OpenCards.isDrawing(await rowOf($, row), word)) await drawCard($, row, word, restated)
}

// 押した語の絵を頼む（絵を描ける面が無ければ、絵なしで）
const drawCard = async ($: EngineInterface, row: string, word: string, restated: string) => {
  const card = WordCards.of(await Answers.of($.model.complete(WordCards.request(await settingsOf($), { word, restated }, await $.session.surfaces()))), { word, restated })
  const kept = OpenCards.kept(await rowOf($, row), word, card)
  if (kept) await update($, drawn, all => WordCards.saving(all, kept, { word, restated }))
  await showCards($, row, list => OpenCards.drawn(list, word, card))
}

// 手順書「語を深める」：開いている欄なら閉じ、なければ開いて書かせる。絵とは別に頼むので、描いている間も押せる。届いた項目は 0.1 秒ずつ順に出す
const pressAspect = async ($: EngineInterface, row: string, restated: string, at: { word: string; aspect: Aspect }) => {
  await showCards($, row, list => OpenCards.aspectPressed(list, at))
  if (!OpenCards.isWriting(await rowOf($, row), at)) return
  const answer = await Answers.of($.model.complete(WordAspects.request(await settingsOf($), at.aspect, { word: at.word, restated })))
  const items = WordAspects.of(answer, at.aspect)
  await showCards($, row, list => OpenCards.written(list, at, items))
  items?.slice(1).forEach((_, n) => $.clock.after(100 * (n + 1), () => void showCards($, row, list => OpenCards.revealed(list, at))))
}

// 描くときに渡す単語の絵の手。row は絵を並べる鍵（指示か返事の段落）、restated は語がある訳の行、id と prefix はボタンの名前の頭
const wordsOf = async ($: EngineInterface, t: Parameters<typeof wordCard>[0], w: Parameters<typeof wordCard>[1], isTerminal: boolean, voice: Voice) => {
  const all = await read($, cards)
  const now = await $.clock.now()
  return {
    // 訳の 1 行を押せる語の並びで。押すとその語の絵が下に出る
    line: (row: string, restated: string, line: Parameters<typeof wordLine>[2], id: string) =>
      wordLine(t, isTerminal, line, WordCards.openedUnits(all[row] ?? []), word => void pressWord($, row, word, restated), id),
    // 開いている絵。拡大・縮小と欄はその絵だけ
    cards: (row: string, restated: string, prefix: string) =>
      (all[row] ?? []).map(s => wordCard(t, w, isTerminal, s, isWide => void showCards($, row, list => OpenCards.resized(list, s.word, isWide)), aspect => void pressAspect($, row, restated, { word: s.word, aspect }), voice, prefix, now)),
  }
}

// 読み上げた文の並び → 文ごとの発音記号（Pronunciations.saving の形）。書いている間は null
const sounds = atom({ plugin: 'claudelingo', key: 'sounds' } as const, {})
// 読み上げている文の並び（改行でつないだもの）→ 読み終わっていない数（重ねて押した分も数える）
const speaking = atom({ plugin: 'claudelingo', key: 'speaking' } as const, {})

// 手順書「読み上げる」：押したらすぐ設定の声で読ませる。段落は 1 つずつ渡せば順に読まれる。読み終わるまで読んでいる数に入れ、読めなければ理由を知らせる
const say = async ($: EngineInterface, lines: string[]) => {
  const { voice, native } = await settingsOf($)
  // 知らせるのは押すごとに 1 回（段落がいくつ読めなくても）
  let isTold = false
  const tell = (error: string) => {
    if (!isTold) $.ui.toast(LingoSettings.wording(native).speakFailed(error))
    isTold = true
  }
  // 声の欄が空なら渡さず、既定の声で読む。末尾の無音は、Bluetooth の遅れで語尾が切れるのを無音側で受けるため
  await showSpeaking($, lines, 1)
  await Promise.all(Pronunciations.spoken(lines).map(line => Result.given($.audio.speak(`${line} [[slnc 500]]`, { voice: voice.trim() || undefined })).then(said => said.either(() => undefined, tell))))
  await showSpeaking($, lines, -1)
}

const showSpeaking = async ($: EngineInterface, lines: string[], by: number) => {
  await update($, speaking, all => ({ ...all, [lines.join('\n')]: (all[lines.join('\n')] ?? 0) + by }))
  $.ui.invalidate('ui.render')
}

// 文は読ませながら、発音記号も頼む。書いた記号は残してすぐ出す
const sayWithSymbols = async ($: EngineInterface, lines: string[]) => {
  void say($, lines)
  if (Pronunciations.isAsked(await read($, sounds), lines)) return
  await showSymbols($, lines, null)
  await showSymbols($, lines, Pronunciations.of(await Answers.of($.model.complete(Pronunciations.request(await settingsOf($), lines)))))
}

const showSymbols = async ($: EngineInterface, lines: string[], symbols?: string[] | null) => {
  await update($, sounds, all => Pronunciations.saving(all, lines, symbols))
  $.ui.invalidate('ui.render')
}

// 描くときに渡す読み上げの手
const voiceOf = async ($: EngineInterface): Promise<Voice> => {
  const all = await read($, sounds)
  const playing = await read($, speaking)
  return { say: text => void say($, [text]), sayWithSymbols: text => void sayWithSymbols($, [text]), symbols: text => Pronunciations.symbol(all, [text], 0), speaking: text => playing[text] ?? 0, practise: (sample, pron) => void practise($, sample, pron) }
}

// 返事の鍵（ReplyTranslations.key：言語の組み合わせと文面）→ その訳。訳している間は null
const replies = atom({ plugin: 'claudelingo', key: 'replies' } as const, {})
// 横のパネルに出している返事の文面と、その訳の鍵（開いたときの設定のもの）
const paneReply = atom({ plugin: 'claudelingo', key: 'paneReply' } as const, { text: '', key: '' })

// 手順書「返事の訳を横に出す」：押した返事をパネルに出し、頼む時なら訳を頼む。頼めない（mod がオフ）なら、パネルの中身は変えない
// パネルは最初の await より前に開く（後だと押したことへの応答とみなされず、144 桁未満の端末では置かれない）。題は設定を読む前に要るので、どの母語でも通じる 🌐
const openReply = async ($: EngineInterface, text: string) => {
  const opened = $.ui.open({ id: REPLY_PANE, title: '🌐' })
  const settings = await settingsOf($)
  const request = ReplyTranslations.request(settings, text)
  if (!request) return
  const key = ReplyTranslations.key(settings, text)
  await update($, paneReply, () => ({ text, key }))
  await opened
  if (!ReplyTranslations.isDue((await read($, replies))[key])) return
  await showReply($, key, null)
  await showReply($, key, ReplyTranslations.checked(text, await Answers.of($.model.complete(request))))
}

const showReply = async ($: EngineInterface, key: string, version: Answer | null) => {
  await update($, replies, all => ({ ...all, [key]: version }))
  $.ui.invalidate('ui.render')
}

// 開いている話す練習。開いていなければ null
const practice = atom({ plugin: 'claudelingo', key: 'practice' } as const, null)

// 手順書「話す練習を開く」：押した文の練習を入力欄の上に開く。同じ文の練習が開いていれば閉じる
const practise = ($: EngineInterface, text: string, pron?: string) => showPractice($, now => SpeakingPractice.pressed(now, text, pron))

// 手順書「声を聞いてコーチする」：入れた文をお手本と比べさせ、届いたら帯に出す。その間に練習が変わっていたら捨てる
const hear = async ($: EngineInterface, heard: string) => {
  const asked = SpeakingPractice.asking(await read($, practice), heard)
  if (!asked) return
  await showPractice($, () => asked)
  const coach = await Answers.of($.model.complete(SpeakingPractice.request(await settingsOf($), asked)))
  await showPractice($, now => SpeakingPractice.coached(now, asked, coach))
}

const showPractice = async ($: EngineInterface, change: (now: Practice | null) => Practice | null) => {
  await update($, practice, change)
  $.ui.invalidate('ui.render')
}

// 打ちかけと、その校正。まだ無いときは null
const draft = atom({ plugin: 'claudelingo', key: 'draft' } as const, null)
// 打つ手が止まるのを待つタイマーと、走っている依頼の止め手。次の打鍵で両方やめる
let pause: Timer | undefined
let stop = new AbortController()

// 手順書「打ちかけを外国語で示す」：打つ手が止まったら 1 回だけ頼み、その間に打たれたら捨てる
const showDraftTranslation = async ($: EngineInterface, text: string, signal: AbortSignal) => {
  const request = DraftTranslations.request(await settingsOf($), text, (await $.command.list()).map(c => c.name))
  if (request) await markDraft($, signal, () => ({ isAsking: true }))
  const version = request && (await Answers.of($.model.complete(request, { signal })))
  const shown = version ? { text, version } : null
  if (signal.aborted) return
  await showDraft($, shown)
  if (shown) await underlineNow($, shown, signal)
}

// 赤線は打鍵の応答か fill でしか付かない。校正が届いたら、同じ文面を fill し直して赤線だけ付ける
// 文字もカーソルも変わらないよう、入力欄が校正した下書きのままで、カーソルが末尾のときだけ
const underlineNow = async ($: EngineInterface, shown: { text: string; version: Answer }, signal: AbortSignal) => {
  const box = await $.prompt.read()
  if (signal.aborted) return
  const decorations = DraftTranslations.underlines(box.text, shown)
  if (box.text === shown.text && box.cursor === box.text.length && decorations.length > 0) await $.prompt.fill({ text: box.text, mode: 'replace', decorations })
}

// 出ている校正の印：下書きが校正した文と違えば古い（薄く）、次を頼んでいる間は頼んでいる（回る印）。印が変わるときだけ描き直す
const markDraft = async ($: EngineInterface, signal: AbortSignal, marks: (shown: Proofread) => { isStale?: boolean; isAsking?: boolean }) => {
  const shown = await read($, draft)
  const marked = shown && { ...shown, ...marks(shown) }
  if (marked && !signal.aborted && (!!marked.isStale !== !!shown.isStale || !!marked.isAsking !== !!shown.isAsking)) await showDraft($, marked)
}

type Proofread = { text: string; version: Answer; isStale?: boolean; isAsking?: boolean }

const showDraft = async ($: EngineInterface, shown: Proofread | null) => {
  await update($, draft, () => shown)
  $.ui.invalidate('ui.render')
}

const cancelDraftTranslation = () => {
  pause?.cancel()
  stop.abort()
}

const translateAfterPause = async ($: EngineInterface, text: string) => {
  cancelDraftTranslation()
  const own = new AbortController()
  stop = own
  await markDraft($, own.signal, shown => ({ isStale: text.trim() !== shown.text.trim(), isAsking: false }))
  const { livePause } = await settingsOf($)
  if (!own.signal.aborted) pause = $.clock.after(Number(livePause) * 1000, () => void showDraftTranslation($, text, own.signal))
}

// 送ったら、入力欄が空になるのに合わせて帯もすぐ消す。✕ でも消す（次に打てばまた出る）
const hideDraftTranslation = async ($: EngineInterface) => {
  cancelDraftTranslation()
  await showDraft($, null)
}

// 打ちかけの校正の帯。校正がなければ undefined
const draftBandOf = async ($: EngineInterface, t: Parameters<typeof draftBand>[0], isTerminal: boolean, settings: Parameters<typeof DraftTranslations.band>[0]) => {
  const shown = await read($, draft)
  const band = DraftTranslations.band(settings, shown)
  if (!shown || !band) return undefined
  const { line, replacement } = band
  // 置き換えるのは、校正した打ちかけのままのときだけ（待ちの間に打たれていたら、古い言い直しになる）。置き換えなかったら、そう知らせる
  const w = LingoSettings.wording(settings.native)
  const replace = async (text: string) => {
    if ((await $.prompt.read()).text.trim() !== shown.text.trim()) return $.ui.toast(w.replaceStale)
    const { isFilled } = await $.prompt.fill({ text, mode: 'replace' })
    // 置き換えた文が今の校正の文（帯は薄くせず、置換も引っ込む）。次の校正はまた手が止まってから
    if (!isFilled) return
    await showDraft($, { text, version: shown.version })
    void translateAfterPause($, text)
  }
  return draftBand(t, w, isTerminal, line, () => void hideDraftTranslation($), replacement ? () => void replace(replacement) : undefined, shown)
}

export const submitted: Hook<'prompt.submit'> = ($, e, next) => {
  // 送信は待たせない。訳は自分の dispatch で走らせる
  $.clock.after(0, () => void showTranslation($, e.origin.kind, PromptTranslations.typed(e.text)))
  // 自分で送ったら下書きは空になる。通知などの送信では、打ちかけの帯を残す
  if (PromptTranslations.isOwn(e.origin.kind)) $.clock.after(0, () => void hideDraftTranslation($))
  return next(e)
}

export const edited: Hook<'prompt.edit'> = async ($, e, next) => {
  const box = await next(e)
  if (box.text !== e.text) void translateAfterPause($, box.text)
  // 校正で直した所が下書きに残っていれば、入力欄のその文字に赤い下線（文字は変えない）
  return { ...box, decorations: [...(box.decorations ?? []), ...DraftTranslations.underlines(box.text, await read($, draft))] }
}

// 入力欄の上は、開いている話す練習と打ちかけの校正を上下に
export const abovePrompt: MatchedHook<'ui.render', { component: 'AbovePrompt' }> = async ($, e, next) => {
  if (e.props.hasSurvey) return next(e)
  // 入力欄の上の帯は端末と Desktop にしかない
  const t = $.ui.resolve(e) as Parameters<typeof practiceBand>[0]
  const settings = await settingsOf($)
  const band = await draftBandOf($, t, e.surface === 'terminal', settings)
  const opened = await read($, practice)
  if (!opened || !settings.enabled) return band ?? next(e)
  // 欄の文は打つたびに残す（描き直しで消えないように）。描き直しはしない
  const hands = { keep: (text: string) => void update($, practice, now => SpeakingPractice.kept(now, text)), hear: (heard: string) => void hear($, heard), say: () => void say($, [opened.sample]), again: () => void showPractice($, SpeakingPractice.again), help: (text: string) => $.ui.toast(text, { timeoutMs: 15000 }), close: () => void showPractice($, () => null) }
  const { Box } = t
  return <Box flexDirection="column" gap={1}>{practiceBand(t, LingoSettings.wording(settings.native), e.surface === 'terminal', opened, SpeakingPractice.shown(settings.native, opened.coach), hands, (await read($, speaking))[opened.sample] ?? 0)}{band}</Box>
}

export const userMessage: MatchedHook<'ui.render', { component: 'UserMessage' }> = async ($, e, next) => {
  const row = await next(e)
  const key = PromptTranslations.key(e.props.text)
  const all = await read($, translations)
  // 文面が constructor などでも、引き継いだ値は拾わない
  const version = Object.hasOwn(all, key) ? all[key] : undefined
  // 訳のない行は、設定を読まずにそのまま（本体の描画を重くしない）
  if (version === undefined) return row
  const settings = await settingsOf($)
  if (version === null) return pendingTranslation($.ui.resolve(e), LingoSettings.wording(settings.native), e.surface === 'terminal', ElementKeys.of('line', e.requestId), row)
  const line = PromptTranslations.line(settings.native, version)
  if (!line) return row
  const t = $.ui.resolve(e)
  const w = LingoSettings.wording(settings.native)
  const voice = await voiceOf($)
  // 訳せていて mod がオンのときだけ押せる（オフなら訳の文だけ。押してもモデルを呼ばない）
  const isPressable = settings.enabled && Result.given(version).either(() => true, () => false)
  const isTerminal = e.surface === 'terminal'
  const id = ElementKeys.of('line', e.requestId)
  if (!isPressable || !settings.card) return withTranslation(t, w, isTerminal, id, row, line, isPressable ? voice : undefined)
  // 単語の絵がオンなら、訳の行の語を押すとその語の絵が下に出る。絵はメッセージごと（同じ文の指示でも分ける）
  const words = await wordsOf($, t, w, isTerminal, voice)
  return withTranslation(t, w, isTerminal, id, row, line, voice, words.line(e.requestId, line.restated, WordLines.of(line.restated), `${id}-word`), words.cards(e.requestId, line.restated, `${id}-`))
}

export const assistantMessage: MatchedHook<'ui.render', { component: 'AssistantMessage' }> = async ($, e, next) => {
  const text = e.props.text
  const settings = await settingsOf($)
  if (!ReplyTranslations.request(settings, text)) return next(e)
  // 端末の返事の頭の行は「● 」の 2 マス下げで描かれる。🌐 もそこにそろえる
  const indent = e.surface === 'terminal' && e.props.isFirstOfReply ? 2 : 0
  return replyBlock($.ui.resolve(e), LingoSettings.wording(settings.native), ElementKeys.of('reply', e.requestId), await next(e), indent, () => void openReply($, text))
}

// パネルに出している返事の訳を段落ごとに描く。訳の語から絵を出すなら、訳の語を押すとその語の絵が出る（訳は行ごと）
// 読み上げは段落ごとに読み、その段落の訳の下に発音記号
export const replyPaneDrawn: MatchedHook<'ui.render', { component: 'Pane'; requestId: typeof REPLY_PANE }> = async ($, e) => {
  const t = $.ui.resolve(e)
  const isTerminal = e.surface === 'terminal'
  const { text, key: reply } = await read($, paneReply)
  const id = ElementKeys.of('reply', text)
  const head = ReplyTranslations.head(text)
  const version = (await read($, replies))[reply]
  const settings = await settingsOf($)
  const w = LingoSettings.wording(settings.native)
  // /clear で状態が空になっても、パネルは開いたまま残る
  if (!text) return replyPane(t, w, isTerminal, id, head, [], w.replyHint)
  if (!version) return replyPane(t, w, isTerminal, id, head, [], ticker(t, isTerminal, `${id}-translating`, 'wait', w.translating))
  const voice = await voiceOf($)
  const words = await wordsOf($, t, w, isTerminal, voice)
  const said = await read($, sounds)
  return Result.given(version).either(value => {
    const { translated, spoken, withCards } = ReplyTranslations.shown(settings, text, value)
    const translations = translated.map(({ restated, at }, n) => {
      const symbol = symbolLine(t, w, isTerminal, `${id}-symbols-${at}`, Pronunciations.symbol(said, spoken, n))
      const key = `${reply}#${at}`
      const lines = WordLines.all(restated).map((line, j) => (withCards ? words.line(key, restated, line, `${id}-word-${at}-${j}`) : wordLine(t, isTerminal, line, new Map())))
      return paragraphTranslation(t, symbol, lines, withCards ? words.cards(key, restated, `${id}-word-${at}-`) : [])
    })
    return replyPane(t, w, isTerminal, id, head, translations, undefined, spoken.length > 0 ? () => void sayWithSymbols($, spoken) : undefined, voice.speaking(spoken.join('\n')))
  }, error => replyPane(t, w, isTerminal, id, head, [], w.translateFailed(error)))
}

