import type { Elements, RenderElement } from 'claude-code'

import type { Wording } from '../../../locales/en'

import { glyph } from '../glyph/glyph'
import { speaker } from '../read-aloud/read-aloud'

export const REPLY_PANE = 'claudelingo-reply'

// 返事のブロック：Claude Code が描いた返事はそのまま、その下に訳を横のパネルに出す 🌐。端末の返事の頭の行の後は indent だけ下げて本文にそろえる
export const replyBlock = (t: Elements[keyof Elements], w: Wording, key: string, row: RenderElement, indent: number, press: () => void) => {
  const { Box } = t
  return (
    <Box flexDirection="column">
      {row}
      <Box paddingLeft={indent}>{glyph(t, `${key}-translate`, '🌐', w.translateAside, press, true)}</Box>
