}

// 訳のパネル：どの返事の訳か分かるよう頭に返事の書き出し（薄く、パネルの幅で 1 行に切る）、段落ごとの訳を少し空けて並べ、最後に読み上げ。訳している間などは訳の代わりに一言（文か、回る一言）
export const replyPane = (t: Elements[keyof Elements], w: Wording, isTerminal: boolean, key: string, head: string, translations: RenderElement[], note?: string | RenderElement, speak?: () => void, playing = 0) => {
  const { Box, Text } = t
  return (
    <Box flexDirection="column" gap={1}>
